import math, json
LON0, LON1, LAT0, LAT1 = 24.2, 44.6, 35.7, 52.9
K = 40.0
C = math.cos(math.radians(44))
W = (LON1 - LON0) * C * K
H = (LAT1 - LAT0) * K
def P(lon, lat): return ((lon - LON0) * C * K, (LAT1 - lat) * K)
def path(pts):
    return 'M' + ' L'.join(f'{x:.1f},{y:.1f}' for x, y in (P(*p) for p in pts)) + 'Z'

