CITIES = {'kyiv': (30.52, 50.45), 'ist': (28.98, 41.01), 'ant': (30.71, 36.90)}
cx = {k: P(*v) for k, v in CITIES.items()}

def arc(a, b, bend):
    (x1, y1), (x2, y2) = cx[a], cx[b]
    mx, my = (x1 + x2) / 2, (y1 + y2) / 2
    dx, dy = x2 - x1, y2 - y1
    L = math.hypot(dx, dy)
    nx, ny = -dy / L, dx / L
    qx, qy = mx + nx * bend * L, my + ny * bend * L
    return f'M{x1:.1f},{y1:.1f} Q{qx:.1f},{qy:.1f} {x2:.1f},{y2:.1f}'

routes = [arc('kyiv', 'ist', .18), arc('kyiv', 'ant', -.16), arc('ist', 'ant', .22)]
ua_lbl, tr_lbl, sea_lbl = P(35.0, 49.2), P(35.6, 38.9), P(34.6, 43.4)

svg = f'''<svg class="geo__svg" viewBox="0 0 {W:.0f} {H:.0f}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Схема офісів Dictum: Київ, Стамбул, Анталія">
<defs><pattern id="geoDots" width="9" height="9" patternUnits="userSpaceOnUse"><circle cx="1.5" cy="1.5" r="1.1" fill="#5E7026" opacity=".28"/></pattern>
<filter id="geoGlow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="5"/></filter></defs>
<rect width="{W:.0f}" height="{H:.0f}" class="geo__land"/>
<g class="geo__water"><path d="{path(BLACK)}"/><path d="{path(AZOV)}"/><path d="{path(MARMARA)}"/><path d="{path(MED)}"/></g>
<g class="geo__other"><path d="{path(CYPRUS)}"/><path d="{path(CRETE)}"/></g>
<g class="geo__home"><path d="{path(UA)}"/><path d="{path(TR_A)}"/><path d="{path(TR_E)}"/></g>
<g class="geo__dots"><path d="{path(UA)}"/><path d="{path(TR_A)}"/><path d="{path(TR_E)}"/></g>
<text class="geo__country" x="{ua_lbl[0]:.0f}" y="{ua_lbl[1]:.0f}">Україна</text>
<text class="geo__country" x="{tr_lbl[0]:.0f}" y="{tr_lbl[1]:.0f}">Туреччина</text>
<text class="geo__sea" x="{sea_lbl[0]:.0f}" y="{sea_lbl[1]:.0f}">Чорне море</text>
<g class="geo__routes">{''.join(f'<path class="geo__route-glow" d="{d}"/>' for d in routes)}{''.join(f'<path class="geo__route" d="{d}" style="animation-delay:{i * .6:.1f}s"/>' for i, d in enumerate(routes))}</g>
<g class="geo__pins">{''.join(f'<circle class="geo__halo" cx="{x:.1f}" cy="{y:.1f}" r="16" style="animation-delay:{i * .8:.1f}s"/><circle class="geo__pin" cx="{x:.1f}" cy="{y:.1f}" r="7"/><circle class="geo__pin-in" cx="{x:.1f}" cy="{y:.1f}" r="3"/>' for i, (x, y) in enumerate(cx.values()))}</g>
</svg>'''
pos = {k: (round(x / W * 100, 1), round(y / H * 100, 1)) for k, (x, y) in cx.items()}
open('region_map.svg', 'w').write(svg)
